review.output:
只输出 JSON，不加 Markdown。每个父类、直接孩子和单独列出的叶恰好出现一次。不要补造未提供的节点。
counterexample 是“孩子或叶符合，但父类不符合”的反例；正向包含为 true 时必须为 null，为 false 时必须提供。
suggested_definition 没有修改建议时为 null；有建议时保持原定义的语言，且整体结论不能是 accept。
{
  "parent_reviews": [
    {
      "proposal_id": "输入提案 ID",
      "parent_checks": {
        "name_definition_alignment": {"verdict": "pass|fail|uncertain", "reason": "简短依据"},
        "common_event_property": {"verdict": "pass|fail|uncertain", "reason": "简短依据"},
        "decidable_boundary": {"verdict": "pass|fail|uncertain", "reason": "简短依据"},
        "useful_abstraction": {"verdict": "pass|fail|uncertain", "reason": "简短依据"},
        "group_coherence": {"verdict": "pass|fail|uncertain", "reason": "简短依据"}
      },
      "edge_reviews": [
        {
          "child_id": "输入孩子 ID",
          "child_entails_parent": "true|false|uncertain",
          "reason": "包含关系的依据，或不成立、无法判断的原因",
          "counterexample": null,
          "broader_scope": "has_extra_cases|no_extra_cases|uncertain",
          "parent_only_example": null,
          "scope_reason": null
        }
      ],
      "leaf_reviews": [
        {
          "leaf_id": "输入叶 ID",
          "entails_parent": "true|false|uncertain",
          "reason": "对该叶的独立包含判断依据",
          "counterexample": null
        }
      ],
      "verdict": "accept|revise|reject|uncertain",
      "definition_review": "父类定义审核摘要",
      "suggested_action": "保留、修改、移除关系、拆分或暂缓的具体建议",
      "suggested_definition": null
    }
  ]
}
